import{_ as d,o as r,c as a,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"التعامل مع الفروع الأربعة لكيانات الاستبدال المظلم","description":"","frontmatter":{},"headers":[],"relativePath":"ar/59-黑暗置换体四类分支处置.md","filePath":"ar/59-黑暗置换体四类分支处置.md"}'),e={name:"ar/59-黑暗置换体四类分支处置.md"};function i(h,t,o,n,s,b){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="التعامل-مع-الفروع-الأربعة-لكيانات-الاستبدال-المظلم" tabindex="-1">التعامل مع الفروع الأربعة لكيانات الاستبدال المظلم <a class="header-anchor" href="#التعامل-مع-الفروع-الأربعة-لكيانات-الاستبدال-المظلم" aria-label="Permalink to &quot;التعامل مع الفروع الأربعة لكيانات الاستبدال المظلم&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>59</td></tr><tr><td>الوحدة</td><td>الأعراق وأشكال الحياة</td></tr><tr><td>الكلمات المفتاحية</td><td>الاندماج التكافلي، الفصل وإعادة التوطين، الختم والمراقبة، الذوبان، التعامل بالفروع</td></tr></tbody></table><h2 id="أولاً-الإطار-العام-للتعامل-بالفروع" tabindex="-1">أولاً: الإطار العام للتعامل بالفروع <a class="header-anchor" href="#أولاً-الإطار-العام-للتعامل-بالفروع" aria-label="Permalink to &quot;أولاً: الإطار العام للتعامل بالفروع&quot;">​</a></h2><p>يعد التعامل مع كيانات الاستبدال المظلم أكثر مجالات حوكمة الحياة تعقيداً في حضارة التكافل المرساة. وعلى عكس عمليات التعامل بالأنواع الثلاثة للحياة الشاذة والطاقة الشاذة، فإن كيانات الاستبدال المظلم، نظراً لبنيتها الخاصة المتمثلة في تعايش الروحين (انظر <em>57-黑暗置换体起源与本质</em>)، تتطلب خطط تعامل بالفروع أكثر تفصيلاً. وفقاً للمبادئ الأخلاقية المقررة في <em>58-双魂伦理准则</em>، وبالدمج مع مرحلة تطور كيان الاستبدال المظلم، وحالة الروح المضيفة الأصلية، وخصائص الروح المظلمة، ومستوى الخطر، ينقسم التعامل مع كيانات الاستبدال المظلم إلى أربعة فروع: نوع الاندماج التكافلي، ونوع الفصل وإعادة التوطين، ونوع الختم والمراقبة، ونوع الذوبان.</p><p>يتبع اختيار فروع التعامل الأربعة المنطق القرارى التالي:</p><table tabindex="0"><thead><tr><th>عامل القرار</th><th>نقاط الاعتبار</th></tr></thead><tbody><tr><td>مرحلة التطور</td><td>من المرحلة الأولى إلى الثالثة تُعطى الأولوية للإنقاذ؛ والمرحلة الرابعة تُقيَّم بحذر؛ وفي المرحلة الخامسة يكون المضيف الأصلي قد هلك</td></tr><tr><td>حالة الروح المضيفة الأصلية</td><td>هل لا تزال الروح المضيفة الأصلية موجودة، وهل يمكنها التعبير عن إرادتها، وهل توجد إمكانية للتعافي</td></tr><tr><td>خصائص الروح المظلمة</td><td>هل تمتلك الروح المظلمة قدرة على التواصل، وهل توجد مساحة للإصلاح، ودرجة التدميرية</td></tr><tr><td>مستوى الخطر</td><td>درجة التهديد للسلامة العامة وحقوق ومصالح الآخرين</td></tr><tr><td>خلاصة المراجعة الأخلاقية</td><td>رأي وحكم لجنة مراجعة أخلاقيات الروحين</td></tr><tr><td>إرادة المضيف الأصلي</td><td>اختيار الروح المضيفة الأصلية عندما تستطيع التعبير عن إرادتها</td></tr></tbody></table><h2 id="ثانياً-النوع-الأول-تعامل-الاندماج-التكافلي" tabindex="-1">ثانياً: النوع الأول: تعامل الاندماج التكافلي <a class="header-anchor" href="#ثانياً-النوع-الأول-تعامل-الاندماج-التكافلي" aria-label="Permalink to &quot;ثانياً: النوع الأول: تعامل الاندماج التكافلي&quot;">​</a></h2><p>يعد تعامل الاندماج التكافلي أكثر أنواع التعامل إيجابية وبناءة بين الفروع الأربعة، وينطبق على كيانات الاستبدال المظلم التي تمتلك فيها الروح المضيفة الأصلية والروح المظلمة إمكانية الوصول إلى المصالحة وتحقيق اندماج الروحين.</p><h3 id="_1-شروط-التطبيق" tabindex="-1">(1) شروط التطبيق <a class="header-anchor" href="#_1-شروط-التطبيق" aria-label="Permalink to &quot;(1) شروط التطبيق&quot;">​</a></h3><p>يجب أن يستوفي تعامل الاندماج التكافلي الشروط التالية في الوقت نفسه:</p><ol><li>أن يكون كيان الاستبدال المظلم في المرحلة الثالثة (فترة تكوُّن الروحين) أو بداية المرحلة الرابعة (بداية فترة الهيمنة المظلمة)؛ وأن تكون الروح المضيفة الأصلية لا تزال موجودة وتمتلك درجة معينة من الوعي الذاتي.</li><li>أن تعبّر الروح المضيفة الأصلية بوضوح عن إرادتها في محاولة الاندماج مع الروح المظلمة، وأن تُعتبر هذه الإرادة حقيقية ومستقلة.</li><li>أن تمتلك الروح المظلمة قدرة معينة على التواصل، وتظهر خصائص غير مدمرة بحتة، وأن تكون لديها إمكانية قبول الاندماج.</li><li>أن يُقيَّم مستوى الخطر على أنه المستوى الثاني (خطر متوسط) أو أقل، وألا يشكل عملية الاندماج تهديداً غير قابل للسيطرة للسلامة العامة.</li><li>أن تتم الموافقة عليها من مراجعة لجنة مراجعة أخلاقيات الروحين.</li></ol><h3 id="_2-هدف-التعامل" tabindex="-1">(2) هدف التعامل <a class="header-anchor" href="#_2-هدف-التعامل" aria-label="Permalink to &quot;(2) هدف التعامل&quot;">​</a></h3><p>من خلال توجيه الروح المضيفة الأصلية والروح المظلمة نحو المصالحة، تحقيق الاندماج العضوي للروحين، وتكوين روح جديدة تمتلك ذكريات المضيف الأصلي وشخصيته وقوته المظلمة في آن واحد. تحتفظ الروح الجديدة المندمجة بجنسية المضيف الأصلي وحقوقه المشروعة، مع حصولها على القدرة على التحكم في الطاقة المظلمة، لتصبح عضواً خاصاً في حضارة التكافل.</p><h3 id="_3-خطوات-التعامل" tabindex="-1">(3) خطوات التعامل <a class="header-anchor" href="#_3-خطوات-التعامل" aria-label="Permalink to &quot;(3) خطوات التعامل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الخطوة</th><th>الاسم</th><th>المحتوى المحدد</th><th>الجهة المسؤولة</th></tr></thead><tbody><tr><td>الخطوة الأولى</td><td>المراجعة الأخلاقية</td><td>تجري لجنة مراجعة أخلاقيات الروحين مراجعة شاملة لخطة الاندماج، وتؤكد مطابقتها للمبادئ الأخلاقية</td><td>لجنة مراجعة أخلاقيات الروحين</td></tr><tr><td>الخطوة الثانية</td><td>توجيه التواصل</td><td>في بيئة خاضعة للسيطرة، يساعد مرشدو الأرواح المحترفون الروح المضيفة الأصلية والروح المظلمة على التواصل، وتعزيز التفاهم المتبادل</td><td>مركز علاج الأرواح + المزارعون</td></tr><tr><td>الخطوة الثالثة</td><td>مفاوضات المصالحة</td><td>توجيه الروحين نحو التوصل إلى اتفاق مصالحة بشأن الهوية المندمجة والذكريات والقدرات ومعايير السلوك وما إلى ذلك</td><td>مركز علاج الأرواح + المستشارون القانونيون</td></tr><tr><td>الخطوة الرابعة</td><td>التحضير للاندماج</td><td>القيام بالتحضيرات السابقة للاندماج مثل تهيئة الجسد، وموازنة الطاقة، والبناء النفسي</td><td>الفريق الطبي + مدربو الزراعة</td></tr><tr><td>الخطوة الخامسة</td><td>اندماج الروحين</td><td>بالمساعدة المشتركة من المزارعين المتقدمين ومعالجي الأرواح، تنفيذ عملية/طقس اندماج الروحين</td><td>المزارعون المتقدمون + معالجو الأرواح</td></tr><tr><td>الخطوة السادسة</td><td>التثبيت بعد الاندماج</td><td>إجراء علاج تثبيتي للروح الجديدة المندمجة، ومراقبة سلامة الروح وقابلية الجسد للتكيف</td><td>الفريق الطبي + فريق المراقبة</td></tr><tr><td>الخطوة السابعة</td><td>تأكيد الهوية</td><td>تأكيد هوية الروح الجديدة المندمجة، والاحتفاظ بجنسية المضيف الأصلي، وتحديث سجلات الهوية</td><td>مؤسسة تسجيل الأسر + مكتب إدارة الحياة</td></tr><tr><td>الخطوة الثامنة</td><td>مساعدة الاندماج الاجتماعي</td><td>تقديم خدمات مساعدة مثل الاستشارة النفسية والإرشاد الزراعي والاندماج الاجتماعي للفرد المندمج</td><td>إدارة شؤون عشرة آلاف عرق + المجتمع</td></tr><tr><td>الخطوة التاسعة</td><td>المتابعة طويلة المدى</td><td>إجراء متابعة ومراقبة طويلة المدى للفرد المندمج لمدة لا تقل عن خمس سنوات، وتقييم استقرار الاندماج والقابلية للتكيف الاجتماعي</td><td>مكتب إدارة الحياة + المجتمع</td></tr></tbody></table><h3 id="_4-الإدارة-بعد-الاندماج" tabindex="-1">(4) الإدارة بعد الاندماج <a class="header-anchor" href="#_4-الإدارة-بعد-الاندماج" aria-label="Permalink to &quot;(4) الإدارة بعد الاندماج&quot;">​</a></h3><p>على الرغم من أن الفرد المندمج يحتفظ بجنسية المضيف الأصلي، إلا أنه يجب أن يخضع لإدارة خاصة:</p><ul><li><strong>التحكم في الطاقة</strong>: يخضع استخدام الفرد المندمج للطاقة المظلمة لرقابة صارمة؛ وتلزم عمليات تفتيش طاقة دورية، ويُحظر استخدام الطاقة المظلمة في الأماكن العامة.</li><li><strong>الإشراف السلوكي</strong>: يجب على الفرد المندمج إبلاغ مكتب إدارة الحياة بحالته السلوكية بشكل دوري، وقبول إشراف المجتمع ومساعدته.</li><li><strong>قيود الزراعة</strong>: لا يجوز للفرد المندمج زراعة التقنيات التي قد تزيد من الصفات المظلمة؛ ويجب الموافقة على خطط الزراعة.</li><li><strong>خطة الطوارئ</strong>: وضع خطة طوارئ لفقدان السيطرة على الطاقة المظلمة لدى الأفراد المندمجين؛ وعند ظهور علامات فقدان السيطرة، يتم تفعيل السيطرة فوراً.</li><li><strong>آلية الخروج</strong>: إذا ظهر عدم استقرار حاد أو سلوك خطير مستمر بعد الاندماج، يمكن إجراء إعادة تقييم وتحويل نوع التعامل.</li></ul><h3 id="_5-التعامل-مع-فشل-الاندماج" tabindex="-1">(5) التعامل مع فشل الاندماج <a class="header-anchor" href="#_5-التعامل-مع-فشل-الاندماج" aria-label="Permalink to &quot;(5) التعامل مع فشل الاندماج&quot;">​</a></h3><p>يحمل اندماج الروحين خطر الفشل؛ وخطط التعامل مع فشل الاندماج:</p><ul><li><strong>إيقاف الاندماج</strong>: إذا حدث عدم استقرار حاد أثناء عملية الاندماج، يتم إيقاف الاندماج فوراً وإعادة الروحين إلى حالتهما قبل الاندماج.</li><li><strong>الاندماج غير الكامل</strong>: إذا ظهر نقص في الروح أو انقسام في الشخصية بعد الاندماج، يتم التحويل إلى تعامل الفصل وإعادة التوطين للمعالجة اللاحقة.</li><li><strong>فقدان السيطرة على الاندماج</strong>: إذا أظهرت الروح الجديدة بعد الاندماج تدميرية غير قابلة للسيطرة، يتم التحويل فوراً إلى تعامل الختم والمراقبة أو الذوبان.</li></ul><h2 id="ثالثاً-النوع-الثاني-تعامل-الفصل-وإعادة-التوطين" tabindex="-1">ثالثاً: النوع الثاني: تعامل الفصل وإعادة التوطين <a class="header-anchor" href="#ثالثاً-النوع-الثاني-تعامل-الفصل-وإعادة-التوطين" aria-label="Permalink to &quot;ثالثاً: النوع الثاني: تعامل الفصل وإعادة التوطين&quot;">​</a></h2><p>ينطبق تعامل الفصل وإعادة التوطين على كيانات الاستبدال المظلم التي لا يمكن للروح المضيفة الأصلية والروح المظلمة فيها الاندماج ولكن يمكن فصلهما؛ ومن خلال عملية فصل الروحين، يتم فصل الروحين وإعادة توطينهما على التوالي.</p><h3 id="_1-شروط-التطبيق-1" tabindex="-1">(1) شروط التطبيق <a class="header-anchor" href="#_1-شروط-التطبيق-1" aria-label="Permalink to &quot;(1) شروط التطبيق&quot;">​</a></h3><ol><li>أن يكون كيان الاستبدال المظلم في المرحلة الثالثة أو الرابعة؛ وأن تكون الروح المضيفة الأصلية لا تزال موجودة ولديها إمكانية التعافي.</li><li>أن تكون محاولة اندماج الروحين قد فشلت أو لا تتوفر شروط الاندماج.</li><li>أن يرى التقييم الفني أن فصل الروحين ممكن، وأن الروح المضيفة الأصلية يمكنها البقاء على قيد الحياة بشكل مستقل بعد الفصل.</li><li>أن تعبّر الروح المضيفة الأصلية بوضوح عن إرادتها في الفصل.</li><li>أن تتم الموافقة عليها من مراجعة لجنة مراجعة أخلاقيات الروحين.</li></ol><h3 id="_2-هدف-التعامل-1" tabindex="-1">(2) هدف التعامل <a class="header-anchor" href="#_2-هدف-التعامل-1" aria-label="Permalink to &quot;(2) هدف التعامل&quot;">​</a></h3><p>من خلال عملية فصل الروحين، فصل الروح المضيفة الأصلية عن الروح المظلمة؛ لتعود الروح المضيفة الأصلية إلى الجسد وتستأنف الحياة الطبيعية، بينما توضع الروح المظلمة في حاوية أو منشأة مخصصة للسيطرة والبحث.</p><h3 id="_3-خطوات-التعامل-1" tabindex="-1">(3) خطوات التعامل <a class="header-anchor" href="#_3-خطوات-التعامل-1" aria-label="Permalink to &quot;(3) خطوات التعامل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الخطوة</th><th>الاسم</th><th>المحتوى المحدد</th><th>الجهة المسؤولة</th></tr></thead><tbody><tr><td>الخطوة الأولى</td><td>المراجعة الأخلاقية</td><td>تراجع لجنة مراجعة أخلاقيات الروحين خطة الفصل، وتؤكد ضرورة الفصل وجدواه</td><td>لجنة مراجعة أخلاقيات الروحين</td></tr><tr><td>الخطوة الثانية</td><td>التحضير للفصل</td><td>القيام بالتحضيرات السابقة للفصل مثل تقييم الجسد، وفحص حالة الروح، وضبط توازن الطاقة</td><td>الفريق الطبي + معالجو الأرواح</td></tr><tr><td>الخطوة الثالثة</td><td>فصل الروحين</td><td>بمساعدة المزارعين المتقدمين ومعالجي الأرواح، تنفيذ عملية فصل الروحين لفصل الروحين عن الجسد</td><td>المزارعون المتقدمون + معالجو الأرواح</td></tr><tr><td>الخطوة الرابعة</td><td>إعادة توطين المضيف الأصلي</td><td>إعادة زرع الروح المضيفة الأصلية في الجسد، وإجراء تثبيت الروح وإعادة تأهيل الجسد</td><td>الفريق الطبي</td></tr><tr><td>الخطوة الخامسة</td><td>وضع الروح المظلمة</td><td>وضع الروح المظلمة المفصولة في حاوية احتواء أرواح مخصصة وتخزينها في منشأة ختم الأرواح</td><td>مكتب إدارة الحياة + الفريق الفني</td></tr><tr><td>الخطوة السادسة</td><td>تعافي المضيف الأصلي</td><td>إجراء إعادة تأهيل جسدية شاملة وعلاج نفسي واستعادة زراعية للمضيف الأصلي، ومساعدته على العودة إلى الحياة الطبيعية</td><td>الفريق الطبي + المستشارون النفسيون</td></tr><tr><td>الخطوة السابعة</td><td>استعادة الهوية</td><td>تأكيد الاستعادة الكاملة لهوية المضيف الأصلي وحقوقه، وتحديث سجلات الهوية</td><td>مؤسسة تسجيل الأسر</td></tr><tr><td>الخطوة الثامنة</td><td>إدارة الروح المظلمة</td><td>إجراء مراقبة وبحث مستمرين على الروح المظلمة المفصولة، واستكشاف إمكانية إصلاحها أو إذابتها</td><td>مكتب إدارة الحياة + مؤسسة البحث العلمي</td></tr></tbody></table><h3 id="_4-وضع-الروح-المظلمة-المفصولة" tabindex="-1">(4) وضع الروح المظلمة المفصولة <a class="header-anchor" href="#_4-وضع-الروح-المظلمة-المفصولة" aria-label="Permalink to &quot;(4) وضع الروح المظلمة المفصولة&quot;">​</a></h3><p>توضع الروح المظلمة المفصولة بالطريقة التالية:</p><ul><li><strong>حاوية الروح</strong>: توضع الروح المظلمة في حاوية احتواء أرواح مخصصة مزودة بأجهزة مثل الحجب الطاقي، وقمع الوعي، والقفل الأمني.</li><li><strong>منشأة الختم</strong>: تُخزن الحاوية في منشأة ختم أرواح مخصصة تطبق أعلى مستوى من إدارة الأمان.</li><li><strong>المراقبة المستمرة</strong>: إجراء مراقبة مستمرة على مدار الساعة لنشاط الوعي وتقلبات الطاقة للروح المظلمة.</li><li><strong>البحث والاستخدام</strong>: تحت مراجعة أخلاقية صارمة، يمكن إجراء أبحاث علمية على الروح المظلمة، واستكشاف جوهر طاقة الهاوية وطرق التطهير.</li><li><strong>التعامل النهائي</strong>: وفقاً لنتائج البحث وتقييم المخاطر، اتخاذ قرار التعامل النهائي مع الروح المظلمة — الإصلاح إلى وجود غير مدمر، أو الختم طويل الأمد، أو التطهير والذوبان.</li></ul><h3 id="_5-مخاطر-الفصل-والاستجابات" tabindex="-1">(5) مخاطر الفصل والاستجابات <a class="header-anchor" href="#_5-مخاطر-الفصل-والاستجابات" aria-label="Permalink to &quot;(5) مخاطر الفصل والاستجابات&quot;">​</a></h3><p>تحمل عملية فصل الروحين المخاطر التالية، والتي يجب وضع خطط استجابة لها:</p><table tabindex="0"><thead><tr><th>الخطر</th><th>خطة الاستجابة</th></tr></thead><tbody><tr><td>تلف الروح المضيفة الأصلية أثناء الفصل</td><td>تقوية الروح قبل الفصل؛ ويوفر المزارعون المتقدمون حماية كاملة أثناء الفصل</td></tr><tr><td>عدم قدرة جسد المضيف الأصلي على التكيف بعد الفصل</td><td>إجراء إعادة تأهيل جسدية شاملة وعلاج تثبيت الروح بعد الفصل</td></tr><tr><td>هروب الروح المظلمة أثناء الفصل</td><td>يُجرى الفصل في منشأة أعلى مستوى من الأمان، مزودة بأجهزة احتواء متعددة</td></tr><tr><td>فصل غير كامل، طاقة مظلمة متبقية</td><td>إجراء علاج تطهير عميق بعد الفصل لإزالة الطاقة المظلمة المتبقية</td></tr><tr><td>صدمة نفسية للروح المضيفة الأصلية بعد الفصل</td><td>تقديم استشارة نفسية طويلة المدى وعلاج عقلي</td></tr></tbody></table><h2 id="رابعاً-النوع-الثالث-تعامل-الختم-والمراقبة" tabindex="-1">رابعاً: النوع الثالث: تعامل الختم والمراقبة <a class="header-anchor" href="#رابعاً-النوع-الثالث-تعامل-الختم-والمراقبة" aria-label="Permalink to &quot;رابعاً: النوع الثالث: تعامل الختم والمراقبة&quot;">​</a></h2><p>ينطبق تعامل الختم والمراقبة على كيانات الاستبدال المظلم التي لا يمكنها الاندماج ولا الفصل، ولكن روحها المضيفة الأصلية لا تزال موجودة والتي لا تتوفر لديها شروط الذوبان الفوري؛ وبوسائل الختم يتم السيطرة على خطرها، مع مراقبة طويلة المدى وتقييم مستمر.</p><h3 id="_1-شروط-التطبيق-2" tabindex="-1">(1) شروط التطبيق <a class="header-anchor" href="#_1-شروط-التطبيق-2" aria-label="Permalink to &quot;(1) شروط التطبيق&quot;">​</a></h3><ol><li>أن يكون كيان الاستبدال المظلم في المرحلة الرابعة (فترة الهيمنة المظلمة)؛ وأن تكون الروح المضيفة الأصلية مكبوتة بعمق ولكنها لم تهلك بعد.</li><li>أن يفتقر كل من الاندماج والفصل إلى الجدوى الفنية أو تكون مخاطرهما مرتفعة للغاية.</li><li>أن يكون مستوى خطر كيان الاستبدال المظلم هو المستوى الثالث (خطر مرتفع)، ولكن لم يبلغ بعد الدرجة التي تتطلب الذوبان الفوري.</li><li>أن يكون لدى الروح المضيفة الأصلية أمل ضعيف في التعافي، وتتطلب وقتاً وظروفاً لانتظار نقطة تحول.</li><li>أن تراجع لجنة مراجعة أخلاقيات الروحين خطة الختم وتوافق عليها.</li></ol><h3 id="_2-هدف-التعامل-2" tabindex="-1">(2) هدف التعامل <a class="header-anchor" href="#_2-هدف-التعامل-2" aria-label="Permalink to &quot;(2) هدف التعامل&quot;">​</a></h3><p>بوسائل الختم، كبح قوة ونشاط الروح المظلمة، والسيطرة على خطر كيان الاستبدال المظلم، مع حماية الروح المضيفة الأصلية من الفناء الكامل، وانتظار نضج فرص التعافي أو التعامل في المراقبة طويلة المدى.</p><h3 id="_3-طرق-الختم" tabindex="-1">(3) طرق الختم <a class="header-anchor" href="#_3-طرق-الختم" aria-label="Permalink to &quot;(3) طرق الختم&quot;">​</a></h3><p>وفقاً لمستوى القوة وخصائص كيان الاستبدال المظلم، تُختار طرق الختم التالية:</p><table tabindex="0"><thead><tr><th>طريقة الختم</th><th>المبدأ</th><th>الأهداف القابلة للتطبيق</th></tr></thead><tbody><tr><td>الختم الطاقي</td><td>استخدام مصفوفات أو أجهزة ختم لكبح تدفق وانبعاث الطاقة المظلمة</td><td>كيانات الاستبدال المظلم منخفضة ومتوسطة مستوى القوة</td></tr><tr><td>الختم المكاني</td><td>ختم كيان الاستبدال المظلم في فضاء معزول مستقل، وقطع الاتصال بالخارج</td><td>كيانات الاستبدال المظلم عالية مستوى القوة أو المعدية</td></tr><tr><td>ختم الوعي</td><td>كبح نشاط وعي الروح المظلمة، ووضعها في حالة خمود أو شبه خمود</td><td>كيانات الاستبدال المظلم ذات الوعي النشط وقدرة الهجوم على الروح</td></tr><tr><td>الختم المتعدد</td><td>استخدام عدة طرق ختم في وقت واحد، لتكوين طبقات حماية متعددة</td><td>كيانات الاستبدال المظلم ذات مستوى قوة مرتفع للغاية أو خصائص خطرة متعددة</td></tr><tr><td>ختم المرساة</td><td>استخدام الصفات الأصلانية لطاقة المرساة في الختم، أقوى طرق الختم</td><td>كيانات الاستبدال المظلم الخطرة على المستوى الكوني</td></tr></tbody></table><h3 id="_4-خطوات-التعامل" tabindex="-1">(4) خطوات التعامل <a class="header-anchor" href="#_4-خطوات-التعامل" aria-label="Permalink to &quot;(4) خطوات التعامل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الخطوة</th><th>الاسم</th><th>المحتوى المحدد</th><th>الجهة المسؤولة</th></tr></thead><tbody><tr><td>الخطوة الأولى</td><td>المراجعة الأخلاقية</td><td>تراجع لجنة مراجعة أخلاقيات الروحين خطة الختم، وتؤكد ضرورة وملاءمة الختم</td><td>لجنة مراجعة أخلاقيات الروحين</td></tr><tr><td>الخطوة الثانية</td><td>التحضير للختم</td><td>تجهيز مصفوفة/جهاز/فضاء الختم، وتخصيص الطاقة والأفراد المطلوبين للختم</td><td>الفريق الفني + المزارعون المتقدمون</td></tr><tr><td>الخطوة الثالثة</td><td>الإخضاع والسيطرة</td><td>بتعاون فريق الأمن، إخضاع كيان الاستبدال المظلم، وضمان عدم وقوع حوادث أثناء عملية الختم</td><td>إدارة الأمن + المزارعون المتقدمون</td></tr><tr><td>الخطوة الرابعة</td><td>تنفيذ الختم</td><td>تنفيذ الختم وفق خطة الختم، وكبح قوة ونشاط الروح المظلمة</td><td>المزارعون المتقدمون + الخاتمون</td></tr><tr><td>الخطوة الخامسة</td><td>التحقق من الختم</td><td>التحقق من فعالية واستقرار الختم، وتأكيد السيطرة على خطر كيان الاستبدال المظلم</td><td>الفريق الفني + فريق المراقبة</td></tr><tr><td>الخطوة السادسة</td><td>النقل والتوظيف</td><td>نقل كيان الاستبدال المظلم المختوم إلى منشأة ختم ومراقبة مخصصة</td><td>إدارة الأمن + مكتب إدارة الحياة</td></tr><tr><td>الخطوة السابعة</td><td>المراقبة المستمرة</td><td>إجراء مراقبة مستمرة على مدار الساعة لحالة الختم، والتحقق دورياً من استقرار الختم</td><td>فريق المراقبة</td></tr><tr><td>الخطوة الثامنة</td><td>إعادة التقييم الدورية</td><td>إجراء إعادة تقييم شاملة كل ستة أشهر، وتقييم حالة الروح المضيفة الأصلية وخصائص الروح المظلمة واستقرار الختم، وتحديد إمكانية تعديل نوع التعامل</td><td>مجموعة خبراء التحديد + لجنة المراجعة الأخلاقية</td></tr><tr><td>الخطوة التاسعة</td><td>صيانة الختم</td><td>صيانة وتعزيز الختم دورياً لمنع ضعفه أو تلفه</td><td>الخاتمون + الفريق الفني</td></tr></tbody></table><h3 id="_5-معايير-منشآت-الختم-والمراقبة" tabindex="-1">(5) معايير منشآت الختم والمراقبة <a class="header-anchor" href="#_5-معايير-منشآت-الختم-والمراقبة" aria-label="Permalink to &quot;(5) معايير منشآت الختم والمراقبة&quot;">​</a></h3><ul><li><strong>الموقع</strong>: تقع منشآت الختم والمراقبة في مناطق نائية ذات جيولوجيا مستقرة وبيئة طاقة مستقرة وكثافة سكانية منخفضة، أو في أبعاد معزولة مستقلة.</li><li><strong>البناء</strong>: تعتمد المنشآت هياكل حماية متعددة، بما في ذلك ثلاث طبقات حماية: الحواجز المادية، والحواجز الطاقية، والقفل المكاني.</li><li><strong>المعدات</strong>: مزودة بأجهزة مراقبة ختم عالية الدقة، وأنظمة تعزيز تلقائية، وأنظمة استجابة للطوارئ، وأنظمة طاقة احتياطية.</li><li><strong>الأفراد</strong>: تطبيق نظام المناوبة على مدار الساعة، مع الخاتمين والمراقبين وحراس الأمن وأفراد الاستجابة للطوارئ.</li><li><strong>الطوارئ</strong>: وضع خطط طوارئ متنوعة لتلف الختم، وهروب الروح المظلمة، وفناء الروح المضيفة الأصلية وغيرها، مع تدريبات دورية.</li></ul><h3 id="_6-رفع-الختم-وتحويله" tabindex="-1">(6) رفع الختم وتحويله <a class="header-anchor" href="#_6-رفع-الختم-وتحويله" aria-label="Permalink to &quot;(6) رفع الختم وتحويله&quot;">​</a></h3><p>في الحالات التالية، يمكن رفع الختم أو تحويل نوع التعامل:</p><ul><li><strong>تعافي المضيف الأصلي</strong>: إذا تعافت الروح المضيفة الأصلية تدريجياً خلال فترة الختم وتوافرت لديها شروط الفصل أو الاندماج، يمكن رفع الختم وتحويله إلى نوع الفصل وإعادة التوطين أو الاندماج التكافلي.</li><li><strong>إصلاح الروح المظلمة</strong>: إذا أظهرت الروح المظلمة إمكانية إصلاح خلال فترة الختم، يمكن رفع الختم في ظروف خاضعة للسيطرة لمحاولات الإصلاح.</li><li><strong>فشل الختم</strong>: إذا لحق بالختم تلف أو ضعف لا يمكن إصلاحه، وكان خطر كيان الاستبدال المظلم غير قابل للسيطرة، يمكن تحويله إلى نوع الذوبان.</li><li><strong>فناء المضيف الأصلي</strong>: إذا هلكت الروح المضيفة الأصلية تماماً خلال فترة الختم، وأصبح كيان الاستبدال المظلم وجوداً مظلماً خالصاً، يمكن تحويله إلى نوع الذوبان أو الاستمرار في الختم حسب خطره.</li></ul><h2 id="خامساً-النوع-الرابع-تعامل-الذوبان" tabindex="-1">خامساً: النوع الرابع: تعامل الذوبان <a class="header-anchor" href="#خامساً-النوع-الرابع-تعامل-الذوبان" aria-label="Permalink to &quot;خامساً: النوع الرابع: تعامل الذوبان&quot;">​</a></h2><p>يعد تعامل الذوبان أشد أنواع التعامل بين الفروع الأربعة، وينطبق على كيانات الاستبدال المظلم التي لا يمكن إنقاذها والخطيرة للغاية؛ ومن خلال إفناء الروح المظلمة (وعند الضرورة إفناء الجسد كله)، يتم القضاء على التهديد.</p><h3 id="_1-شروط-التطبيق-3" tabindex="-1">(1) شروط التطبيق <a class="header-anchor" href="#_1-شروط-التطبيق-3" aria-label="Permalink to &quot;(1) شروط التطبيق&quot;">​</a></h3><p>ينطبق تعامل الذوبان على الحالات التالية:</p><ol><li>أن يكون كيان الاستبدال المظلم في المرحلة الخامسة (فترة الاستبدال الكامل)؛ وأن تكون الروح المضيفة الأصلية قد هلكت تماماً، والجسد تحت السيطرة الكاملة للروح المظلمة، ليصبح وجوداً مظلماً خالصاً.</li><li>أن يكون كيان الاستبدال المظلم في المرحلة الرابعة؛ وأن تكون الروح المضيفة الأصلية لا تزال موجودة ولكن لا يمكنها التعافي، والاندماج والفصل والختم جميعها غير مجدية، وخطرها في تصاعد مستمر.</li><li>أن يكون مستوى خطر كيان الاستبدال المظلم هو المستوى الرابع (خطر مرتفع للغاية)، مع قوة تدميرية على المستوى الكوني، تهدد بقاء الحضارة مباشرة، ولا يمكن لطرق التعامل الأخرى السيطرة على تهديده.</li><li>في تعامل الختم والمراقبة، أن يكون الختم قد فشل ولا يمكن إعادة تطبيقه، وخطر كيان الاستبدال المظلم غير قابل للسيطرة.</li><li>أن تراجع لجنة مراجعة أخلاقيات الروحين خطة الذوبان وتوافق عليها (يمكن التعامل أولاً ثم الموافقة بأثر رجعي في حالات الطوارئ شديدة الخطورة).</li></ol><h3 id="_2-مبادئ-الذوبان" tabindex="-1">(2) مبادئ الذوبان <a class="header-anchor" href="#_2-مبادئ-الذوبان" aria-label="Permalink to &quot;(2) مبادئ الذوبان&quot;">​</a></h3><p>يرتبط تعامل الذوبان بإفناء الحياة ويجب أن يتبع بدقة المبادئ التالية:</p><ul><li><strong>مبدأ الملاذ الأخير</strong>: يجب أن يكون الذوبان هو الملاذ الأخير عندما تكون جميع طرق التعامل الأخرى غير مجدية.</li><li><strong>مبدأ التناسب</strong>: يجب أن تتوافق شدة الذوبان مع درجة التهديد؛ ويُحظر الاستخدام المفرط للقوة.</li><li><strong>مبدأ تقليل المعاناة</strong>: يجب أن يتبنى الذوبان قدر الإمكان طرقاً سريعة وغير مؤلمة، لتقليل معاناة الروح المظلمة (والروح المضيفة الأصلية إن كانت لا تزال موجودة).</li><li><strong>مبدأ احترام المضيف الأصلي</strong>: إذا كانت الروح المضيفة الأصلية لا تزال موجودة، يجب إبقاؤها واعية ومحافظة على كرامتها قدر الإمكان قبل الذوبان؛ وعند الضرورة، السماح للمضيف الأصلي بتوديع الأقارب والأصدقاء.</li><li><strong>مبدأ التسجيل الكامل</strong>: يتم تسجيل عملية الذوبان بالكامل، لتكوين أرشيف كامل للمراجعة والتتبع.</li><li><strong>مبدأ المراجعة اللاحقة</strong>: بعد اكتمال الذوبان، إجراء مراجعة لاحقة، وتقييم ضرورة وملاءمة الذوبان، وتلخيص الدروس المستفادة.</li></ul><h3 id="_3-طرق-الذوبان" tabindex="-1">(3) طرق الذوبان <a class="header-anchor" href="#_3-طرق-الذوبان" aria-label="Permalink to &quot;(3) طرق الذوبان&quot;">​</a></h3><p>وفقاً لمستوى القوة وخصائص كيان الاستبدال المظلم، تُختار طرق الذوبان التالية:</p><table tabindex="0"><thead><tr><th>طريقة الذوبان</th><th>المبدأ</th><th>الأهداف القابلة للتطبيق</th></tr></thead><tbody><tr><td>ذوبان التطهير بالنور المقدس</td><td>استخدام طاقة النور المقدس عالية الكثافة لتطهير الروح المظلمة، وجعلها تتبدد في الضوء</td><td>كيانات الاستبدال المظلم منخفضة ومتوسطة مستوى القوة</td></tr><tr><td>فن إفناء الروح</td><td>مهاجمة وإفناء نواة الروح المظلمة مباشرة، والتسبب في فناءها الكامل</td><td>كيانات الاستبدال المظلم عالية مستوى القوة</td></tr><tr><td>ذوبان النفي المكاني</td><td>نفي كيان الاستبدال المظلم إلى فضاء الفراغ أو نهاية الزمن، وجعله يذوب في الاضمحلال الزمكاني</td><td>كيانات الاستبدال المظلم ذات دفاع جسدي قوي</td></tr><tr><td>ذوبان الأصلانية المرساة</td><td>استدعاء الطاقة الأصلانية للمرساة، وتحليل كيان الاستبدال المظلم وإعادته إلى أصل الكون</td><td>كيانات الاستبدال المظلم الخطرة على المستوى الكوني</td></tr><tr><td>الذوبان المشترك لقوى الأبعاد المتعددة</td><td>تتحد قوى الأبعاد العليا المتعددة، وتستخدم القوة المطلقة لكبح وإفناء كيان الاستبدال المظلم</td><td>كيانات الاستبدال المظلم ذات مستوى القوة المرتفع للغاية</td></tr><tr><td>ذوبان التفجير الذاتي المحرض</td><td>تحت سيطرة صارمة، إحداث تفجير ذاتي للطاقة المظلمة لكيان الاستبدال المظلم، وإذابته في الانفجار الطاقي</td><td>كيانات الاستبدال المظلم ذات الطاقة غير المستقرة</td></tr></tbody></table><h3 id="_4-خطوات-التعامل-1" tabindex="-1">(4) خطوات التعامل <a class="header-anchor" href="#_4-خطوات-التعامل-1" aria-label="Permalink to &quot;(4) خطوات التعامل&quot;">​</a></h3><table tabindex="0"><thead><tr><th>الخطوة</th><th>الاسم</th><th>المحتوى المحدد</th><th>الجهة المسؤولة</th></tr></thead><tbody><tr><td>الخطوة الأولى</td><td>المراجعة الأخلاقية/الموافقة الطارئة</td><td>في الظروف العادية، تُراجع وتُوافق عليها لجنة مراجعة أخلاقيات الروحين؛ وفي حالات الطوارئ شديدة الخطورة، يأمر بها أعلى مسؤول في الموقع، مع الموافقة بأثر رجعي</td><td>لجنة مراجعة أخلاقيات الروحين / أعلى مسؤول في الموقع</td></tr><tr><td>الخطوة الثانية</td><td>وضع الخطة</td><td>وضع خطة ذوبان مفصلة، تشمل طرق الذوبان، وتوزيع القوى، وتدابير السلامة، وخطط الطوارئ، وتقييم الأثر البيئي</td><td>مقر القيادة القتالية + مجموعة الخبراء الفنيين</td></tr><tr><td>الخطوة الثالثة</td><td>حشد القوى</td><td>حشد المزارعين والأفراد الفنيين والمعدات وموارد الطاقة المطلوبة للذوبان</td><td>إدارة الأمن + المزارعون المتقدمون</td></tr><tr><td>الخطوة الرابعة</td><td>عزل المنطقة</td><td>عزل منطقة الذوبان، وإجلاء الأفراد المحيطين، وإقامة خطوط أمان</td><td>إدارة الأمن + الحكومة المحلية</td></tr><tr><td>الخطوة الخامسة</td><td>الإخضاع والكبح</td><td>استخدام قوة الكبح أولاً للسيطرة على تحركات كيان الاستبدال المظلم، ومنع هروبه أو تدميره الأكبر</td><td>المزارعون المتقدمون + قوات الأمن</td></tr><tr><td>الخطوة السادسة</td><td>تنفيذ الذوبان</td><td>تنفيذ الذوبان وفق خطة الذوبان، مع مراقبة شاملة للعملية؛ وعند أي خلل، تفعيل خطة الطوارئ فوراً</td><td>المزارعون المتقدمون + الفريق الفني</td></tr><tr><td>الخطوة السابعة</td><td>تأكيد الفناء</td><td>تأكيد فناء الروح المظلمة (والجسد) تماماً، وفحص وجود طاقة متبقية أو شظايا روح</td><td>فريق المراقبة + مجموعة خبراء التحديد</td></tr><tr><td>الخطوة الثامنة</td><td>استعادة البيئة</td><td>إجراء استعادة بيئية لمنطقة الذوبان، وإزالة الطاقة المظلمة المتبقية، واستعادة التوازن البيئي</td><td>إدارة البيئة الإيكولوجية</td></tr><tr><td>الخطوة التاسعة</td><td>معالجة العواقب</td><td>إبلاغ أقارب وأصدقاء المضيف الأصلي (إذا هلك المضيف الأصلي)، ومعالجة تركة المضيف الأصلي، وتقديم استشارة نفسية</td><td>إدارة الشؤون المدنية + المستشارون النفسيون</td></tr><tr><td>الخطوة العاشرة</td><td>الأرشفة والمراجعة اللاحقة</td><td>أرشفة السجلات الكاملة لعملية الذوبان، وإجراء مراجعة لاحقة، وتقييم الضرورة والملاءمة</td><td>مكتب إدارة الحياة + لجنة المراجعة الأخلاقية</td></tr></tbody></table><h3 id="_5-إجراءات-الذوبان-الطارئ" tabindex="-1">(5) إجراءات الذوبان الطارئ <a class="header-anchor" href="#_5-إجراءات-الذوبان-الطارئ" aria-label="Permalink to &quot;(5) إجراءات الذوبان الطارئ&quot;">​</a></h3><p>بالنسبة لكيانات الاستبدال المظلم من المستوى الرابع (خطر مرتفع للغاية) التي تهدد بقاء الحضارة مباشرة، تنطبق إجراءات الذوبان الطارئ:</p><ol><li>يمكن لأعلى مسؤول في الموقع أن يأمر مباشرة ببدء الذوبان الطارئ دون مراجعة أخلاقية مسبقة، ولكن يجب عليه إبلاغ لجنة مراجعة أخلاقيات الروحين للتسجيل خلال 24 ساعة بعد الذوبان.</li><li>يمكن للذوبان الطارئ أن يحشد أعلى مستوى من القوى وموارد الطاقة في الحضارة، بما في ذلك الاستدعاء المركزي لطاقة المرساة والعمل المشترك لقوى الأبعاد العليا المتعددة.</li><li>الهدف الأولوي للذوبان الطارئ هو القضاء على التهديد وحماية الحياة وأمن الحضارة، وليس السعي إلى &quot;أناقة&quot; أو &quot;خلو من الألم&quot; لطريقة الذوبان (ولكن يجب تقليل الأضرار الجانبية قدر الإمكان).</li><li>بعد الذوبان الطارئ، يجب إجراء تقييم واستعادة بيئية شاملين، لمنع الطاقة المظلمة المتبقية والكوارث الثانوية.</li><li>يجب أن تخضع حالات الذوبان الطارئ لمراجعة لاحقة وتحليل معمق، وتلخيص الدروس المستفادة، وتحسين آليات الإنذار والتعامل.</li></ol><h2 id="سادساً-آلية-التحويل-بين-فروع-التعامل-الأربعة" tabindex="-1">سادساً: آلية التحويل بين فروع التعامل الأربعة <a class="header-anchor" href="#سادساً-آلية-التحويل-بين-فروع-التعامل-الأربعة" aria-label="Permalink to &quot;سادساً: آلية التحويل بين فروع التعامل الأربعة&quot;">​</a></h2><p>إن تعامل كيانات الاستبدال المظلم ليس ثابتاً؛ وفقاً لتغيرات الوضع أثناء عملية التعامل، يمكن التحويل بين الفروع الأربعة:</p><table tabindex="0"><thead><tr><th>اتجاه التحويل</th><th>شروط التحويل</th><th>إجراءات التحويل</th></tr></thead><tbody><tr><td>اندماج ← فصل</td><td>فشلت محاولة الاندماج أو ظهر عدم استقرار حاد بعد الاندماج</td><td>إعادة تقييم؛ وبعد موافقة المراجعة الأخلاقية، التحويل إلى فصل</td></tr><tr><td>اندماج ← ختم</td><td>فشل الاندماج وتعذر الفصل؛ وهناك حاجة للسيطرة على المخاطر</td><td>إعادة تقييم؛ وبعد موافقة المراجعة الأخلاقية، التحويل إلى ختم</td></tr><tr><td>اندماج ← ذوبان</td><td>فقدان السيطرة على الاندماج؛ والروح الجديدة ذات تدميرية غير قابلة للسيطرة</td><td>تقييم طارئ؛ التحويل فوراً إلى ذوبان</td></tr><tr><td>فصل ← ختم</td><td>فشل الفصل أو عدم قدرة المضيف الأصلي على التعافي بعد الفصل؛ وهناك حاجة للسيطرة على المخاطر</td><td>إعادة تقييم؛ وبعد موافقة المراجعة الأخلاقية، التحويل إلى ختم</td></tr><tr><td>فصل ← ذوبان</td><td>هربت الروح المظلمة أثناء الفصل وأصبحت غير قابلة للسيطرة</td><td>تقييم طارئ؛ التحويل فوراً إلى ذوبان</td></tr><tr><td>ختم ← اندماج</td><td>خلال فترة الختم، تعافت الروح المضيفة الأصلية وتوافرت شروط الاندماج</td><td>اكتشاف في إعادة التقييم الدورية؛ وبعد موافقة المراجعة الأخلاقية، التحويل إلى اندماج</td></tr><tr><td>ختم ← فصل</td><td>خلال فترة الختم، تعافت الروح المضيفة الأصلية وتوافرت شروط الفصل</td><td>اكتشاف في إعادة التقييم الدورية؛ وبعد موافقة المراجعة الأخلاقية، التحويل إلى فصل</td></tr><tr><td>ختم ← ذوبان</td><td>فشل الختم وتعذر إعادة تطبيقه؛ والخطر غير قابل للسيطرة</td><td>تقييم طارئ؛ التحويل فوراً إلى ذوبان</td></tr><tr><td>ذوبان ← أخرى</td><td>الذوبان هو الملاذ الأخير؛ وبمجرد تنفيذه لا رجعة فيه</td><td>غير قابل للتطبيق</td></tr></tbody></table><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>إن التعامل مع الفروع الأربعة لكيانات الاستبدال المظلم هو تتويج لحوكمة الحياة في حضارة التكافل المرساة. من الإنقاذ النشط للاندماج التكافلي، إلى القطع الدقيق للفصل وإعادة التوطين، إلى الانتظار الصبور للختم والمراقبة، إلى الملاذ الأخير للذوبان، تشكل الفروع الأربعة طيفاً كاملاً من التعامل من الألطف إلى الأشد، يغطي جميع الحالات الممكنة لكيانات الاستبدال المظلم. يدافع نظام التعامل هذا في الوقت نفسه عن الخط الأخلاقي الأساسي &quot;بذل كل جهد لإنقاذ كل روح&quot; وعن خط السلامة الأساسي &quot;القضاء الحازم على التهديدات غير القابلة للسيطرة&quot;، مجسداً التوازن الدقيق لحضارة التكافل بين أخلاقيات الحياة وحوكمة السلامة.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (أصل وجوهر كيانات الاستبدال المظلم)</li><li>58-双魂伦理准则 (أخلاقيات الروحين)</li><li>54-奇特生命三类处置流程 (عملية التعامل مع الأنواع الثلاثة من الحياة الشاذة)</li><li>48-司法体系与裁决机制 (النظام القضائي وآلية الفصل)</li></ul>',74)])])}const c=d(e,[["render",i]]);export{_ as __pageData,c as default};
